@layer components {
  :where([data-control-family="kbd"][data-slot="root"]) {
    --kbd-radius: var(--radius-control);
    --kbd-background: oklch(from var(--card) l c h / 0.6);
    --kbd-foreground: var(--muted-foreground);
    --kbd-border-color: var(--border);
    --kbd-shadow: var(--shadow-sm);
    border-radius: var(--kbd-radius);
    background: var(--kbd-background);
    box-shadow: inset 0 0 0 1px var(--kbd-border-color), var(--kbd-shadow);
    color: var(--kbd-foreground);
    font-size: var(--text-micro);
  }

  :where([data-control-family="kbd"][data-slot="root"]) {
    font-family: var(--font-sans);
    font-weight: var(--font-weight-medium);
  }
}

@property --kbd-radius {
  syntax: "<length-percentage>";
  inherits: true;
  initial-value: 0px;
}

@property --kbd-background {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --kbd-foreground {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --kbd-border-color {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --kbd-shadow {
  syntax: "*";
  inherits: true;
}

import type { ComponentProps, CSSProperties } from "react";
import type { KbdProps } from "@/components/control-ui/contracts";
import type { KbdKnobStyle } from "@/components/control-ui/knob-contracts";
import { cn } from "@/components/control-ui/lib/cn";

export function Kbd({ className, ...props }: KbdProps) {
  return (
    <kbd
      data-control-ui="kbd"
      data-control-family="kbd"
      data-slot="root"
      className={cn("inline-flex h-5 min-w-5 select-none items-center justify-center gap-1 px-1.5", className)}
      {...props}
    />
  );
}

export function KbdGroup({ className, ...props }: ComponentProps<"span"> & { style?: CSSProperties & KbdKnobStyle }) {
  return (
    <span
      data-control-ui="kbd"
      data-control-family="kbd"
      data-slot="group"
      className={cn("inline-flex items-center gap-1", className)}
      {...props}
    />
  );
}
